static HIMAGELIST Image(){HDC dc=CreateCompatibleDC(nullptr);BITMAPINFO bi{};bi.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);bi.bmiHeader.biWidth=16;bi.bmiHeader.biHeight=-16;bi.bmiHeader.biPlanes=1;bi.bmiHeader.biBitCount=32;void* pixels=nullptr;HBITMAP bitmap=CreateDIBSection(dc,&bi,DIB_RGB_COLORS,&pixels,nullptr,0);for(int i=0;i<256;i++)static_cast<DWORD*>(pixels)[i]=0xff15d72b;HIMAGELIST image=ImageList_Create(16,16,ILC_COLOR32|ILC_MASK,1,0);ImageList_Add(image,bitmap,nullptr);DeleteObject(bitmap);DeleteDC(dc);return image;}
