// Native v6 x86 image lists can round an opaque color down by one LSB
// during alpha conversion. Match only this authored sentinel's adjacent
// channel values; empty/native background pixels still cannot pass.
static bool GlyphSentinel(DWORD color){
    const DWORD red=(color>>16)&255,green=(color>>8)&255,blue=color&255;
    return (red==0x15||red==0x14)&&(green==0xD7||green==0xD6)&&
        (blue==0x2B||blue==0x2A);
}
static RECT Ink(HWND t,int width,int height){HDC dc=CreateCompatibleDC(nullptr);BITMAPINFO bi{};bi.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);bi.bmiHeader.biWidth=width;bi.bmiHeader.biHeight=-height;bi.bmiHeader.biPlanes=1;bi.bmiHeader.biBitCount=32;void* p=nullptr;HBITMAP b=CreateDIBSection(dc,&bi,DIB_RGB_COLORS,&p,nullptr,0);HGDIOBJ old=SelectObject(dc,b);RECT all{0,0,width,height};FillRect(dc,&all,(HBRUSH)GetStockObject(BLACK_BRUSH));SendMessageW(t,WM_PRINTCLIENT,(WPARAM)dc,PRF_CLIENT|PRF_ERASEBKGND);GdiFlush();RECT ink{width,height,0,0};for(int y=0;y<height;y++)for(int x=0;x<width;x++){DWORD color=static_cast<DWORD*>(p)[y*width+x]&0xffffff;if(GlyphSentinel(color)){ink.left=std::min<LONG>(ink.left,x);ink.right=std::max<LONG>(ink.right,x+1);ink.top=std::min<LONG>(ink.top,y);ink.bottom=std::max<LONG>(ink.bottom,y+1);}}SelectObject(dc,old);DeleteObject(b);DeleteDC(dc);return ink;}
